using System;using System.Collections.Generic;using BitBankWP_places_app.Model;
class Program {static void Main(){var p=new PlaceItem();var events=new List<string>();p.PropertyChanged+=(s,e)=>events.Add(e.PropertyName);p.GeoPoint=new Parse.ParseGeoPoint(12,34);if(p.Lat!=12||p.Lon!=34||p.GeoPoint.Latitude!=12||p.Position.Longitude!=34)throw new Exception("GeoPoint assignment discarded");foreach(var name in new[]{"Lat","Lon","GeoPoint","Position"})if(!events.Contains(name))throw new Exception("Missing notification "+name);events.Clear();p.Lat=56;p.Lon=78;if(p.Position.Latitude!=56||p.GeoPoint.Longitude!=78||!events.Contains("Position"))throw new Exception("Coordinate changes leave stale bindings");Console.WriteLine("PASS: geographic assignment, both coordinate projections and binding notifications");}}
